const WHEEL_ITEM_H = 40;
const WHEEL_MINUTES = ["00", "05", "10", "15", "20", "25", "30", "35", "40", "45", "50", "55"];
const WHEEL_STEP = 5; // the wheel's minute granularity

/* How far ahead the picker *opens*. The wheel offers everything from now on, but
 * the pre-selected time is a couple of hours out — far enough that there's a
 * real choice of shows to aim for, near enough to still be this afternoon. */
const CONSTRAINT_DEFAULT_LEAD_MINUTES = 120;

/* The earliest slot the wheel offers: the next whole five minutes from now,
 * never past the last slot of the day. */
function earliestWheelMinutes() {
  return Math.min(Math.ceil(NOW.minutes / WHEEL_STEP) * WHEEL_STEP, 23 * 60 + 55);
}
/* Where the wheel opens when there's nothing chosen yet: now + the default lead,
 * snapped to the wheel's five-minute grid and kept inside today. */
function defaultConstraintTime() {
  const target = Math.round((NOW.minutes + CONSTRAINT_DEFAULT_LEAD_MINUTES) / WHEEL_STEP) * WHEEL_STEP;
  return minutesToTime(Math.max(earliestWheelMinutes(), Math.min(target, 23 * 60 + 55)));
}
/* Minutes offered for a given hour. Every hour gets the full set except the
 * current one, where minutes already gone are dropped — the wheel never offers
 * a time in the past. */
function minutesForHour(hh) {
  const earliest = earliestWheelMinutes();
  if (parseInt(hh, 10) !== Math.floor(earliest / 60)) return WHEEL_MINUTES;
  const floor = earliest % 60;
  return WHEEL_MINUTES.filter((m) => +m >= floor);
}
/* Keep the minute wheel's range in step with the chosen hour, holding on to the
 * chosen minute where it survives the new range. */
function syncMinuteWheelRange(hh, smooth) {
  const mw = document.getElementById("minWheel");
  if (!mw) return;
  const values = minutesForHour(hh);
  const same =
    (mw._values || []).length === values.length &&
    (mw._values || []).every((v, i) => v === values[i]);
  if (same) return;
  const prev = readWheel(mw);
  populateWheel(mw, values);
  scrollWheelTo(mw, values.includes(prev) ? prev : values[0], smooth);
}

