// Minimal no-op Leaflet stand-in — the map isn't what we're looking at, and the
// real CDN is unreachable from this container. Enough surface that app.js's map
// calls don't throw and the rest of the page renders.
(function () {
  const chain = () =>
    new Proxy(function () {}, {
      get: () => chain(),
      apply: () => chain(),
      construct: () => chain(),
    });
  window.L = new Proxy({}, { get: () => chain() });
})();

